/* ajuda-conteudo.js — artigos redigidos e conferidos (como fazer, dúvidas, normas). 85 itens. */
(window.ERP_AJUDA = window.ERP_AJUDA || []).push.apply(window.ERP_AJUDA, [{"id":"como-lancar-conta-pagar","tipo":"como","titulo":"Como lançar uma conta a pagar","url":"contas_pagar.html","modulo":"Financeiro","resumo":"Registre uma despesa ou boleto para não perder o vencimento.","passos":["Abra Contas a Pagar.","No quadro \"Novo Lançamento de Conta a Pagar\", preencha a descrição (despesa ou nota fiscal), o fornecedor, o valor e o vencimento. Os campos com * são obrigatórios.","Se o fornecedor ainda não existe, use o botão de cadastrar novo fornecedor ao lado do campo.","Escolha o centro de custo e a conta contábil (DRE) se quiser separar a despesa nos relatórios; são opcionais.","Para uma despesa que se repete, marque \"Custo recorrente?\" e informe o número de meses ou parcelas.","Clique em \"Adicionar Conta a Pagar\". Ela aparece na lista com status Pendente."],"dica":"Para corrigir depois, use o lápis da linha. Se a conta tem parcelas, o sistema pergunta se a alteração vale só para aquela parcela.","palavras":["boleto","fornecedor","despesa","vencimento","parcelar","recorrente","nota de compra"]},{"id":"como-pagar-conta","tipo":"como","titulo":"Como dar baixa (pagar) uma conta a pagar","url":"contas_pagar.html","modulo":"Financeiro","resumo":"Quando você paga o boleto, registre a baixa para o dinheiro sair do saldo da conta.","passos":["Na lista de Contas a Pagar, ache a conta (use a busca por nome, descrição ou código).","Clique no botão verde \"Pagar\" da linha.","Informe a data do pagamento e a conta de origem (de onde o dinheiro saiu).","Se houve juros, multa ou desconto, preencha nos campos próprios; o \"valor efetivamente pago\" é calculado.","Clique em \"Confirmar Pagamento\". O status muda para Pago."],"dica":"Pagou errado? O ícone de desfazer na linha devolve a conta para Pendente.","palavras":["baixar","quitar","liquidar","pagamento","juros","multa","desfazer pagamento"]},{"id":"como-lancar-conta-receber","tipo":"como","titulo":"Como lançar uma conta a receber","url":"contas_receber.html","modulo":"Financeiro","resumo":"Registre uma venda ou cobrança que você ainda vai receber.","passos":["Abra Contas a Receber.","Em \"Novo Lançamento de Conta a Receber\", preencha a descrição, o cliente, o valor e o vencimento (campos com *).","Cliente novo? Use o botão de cadastrar novo cliente ao lado do campo.","Clique em \"Adicionar Conta a Receber\"."],"palavras":["cobrança","cliente","venda","faturar","mensalidade"]},{"id":"como-receber-conta","tipo":"como","titulo":"Como dar baixa (receber) uma conta a receber","url":"contas_receber.html","modulo":"Financeiro","resumo":"Registre o dinheiro que entrou para atualizar o saldo e o fluxo de caixa.","passos":["Na lista de Contas a Receber, ache o título.","Clique no botão verde \"Receber\" da linha.","Informe a data do recebimento e a conta bancária de destino.","Preencha juros/multa recebidos ou desconto concedido, se houver.","Clique em \"Confirmar Entrada\"."],"dica":"O ícone de desfazer na linha devolve o título para Pendente e a entrada some do Fluxo de Caixa.","palavras":["baixar","entrada","recebimento","desfazer recebimento"]},{"id":"como-conciliar-ofx","tipo":"como","titulo":"Como conciliar o extrato do banco (arquivo OFX)","url":"conciliacao.html","modulo":"Financeiro","resumo":"Compara o extrato do banco com o que você lançou no sistema.","passos":["No internet banking, baixe o extrato em formato OFX.","Abra Conciliação Bancária, escolha a conta bancária e selecione o arquivo OFX.","Clique em \"Processar OFX\".","Use \"Sugerir conciliação automática\" para o sistema casar os lançamentos de mesmo valor; confira e clique em \"Aplicar selecionadas\".","Os que sobrarem: abra o lançamento, escolha o título correspondente (os de mesmo valor aparecem primeiro, com ★) e clique em \"Vincular e conciliar\".","Imprima a conciliação se precisar guardar."],"palavras":["extrato","ofx","banco","conciliar","conferir saldo"]},{"id":"como-importar-xml","tipo":"como","titulo":"Como importar notas fiscais (XML)","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"Traga as notas de entrada e saída para o sistema a partir dos arquivos XML.","passos":["Abra Notas Fiscais (XML) e entre na aba \"Importar XML\".","Confirme a empresa e selecione os arquivos XML (pode escolher vários de uma vez).","Em \"Quando o CNPJ não bater\", escolha o que o sistema deve fazer com notas de outro CNPJ.","Confira a prévia. Desmarque o que não quiser e use \"Limpar prévia\" para recomeçar.","Clique em \"Importar notas selecionadas\".","Veja o resultado na aba \"Notas\" e os totais por mês em \"Resumo mensal\"."],"dica":"Notas já importadas não são duplicadas. Nas notas de 2026 em diante, o sistema também lê o IBS e a CBS de cada item.","palavras":["xml","nfe","nfse","nfce","importar nota","arquivo","entrada","saída"]},{"id":"como-apuracao-ibs-cbs","tipo":"como","titulo":"Como ver a apuração de IBS e CBS","url":"fiscal_notas.html#ibs","modulo":"Fiscal","resumo":"Mostra, mês a mês, o IBS e a CBS a recolher e o crédito a transportar.","passos":["Importe as notas do período (veja \"Como importar notas fiscais (XML)\").","Abra a aba \"Apuração IBS/CBS\".","Confira, por mês: CBS débito, CBS crédito, CBS a recolher e o crédito a transportar (o mesmo para o IBS).","Use \"Imprimir\" para gerar o relatório."],"dica":"Em 2026 as alíquotas são de teste (CBS 0,9% e IBS 0,1%) e valem como informação; a cobrança de verdade começa em 2027.","palavras":["reforma tributária","ibs","cbs","crédito","apuração"],"fonte":"Lei Complementar 214/2025 e Nota Técnica 2025.002 da NF-e","revisado":"24/11/2026"},{"id":"como-simular-2027","tipo":"como","titulo":"Como simular os impostos de 2027 (reforma tributária)","url":"fiscal_contabil.html","modulo":"Fiscal","resumo":"Compare quanto de imposto a empresa pagaria com as regras novas.","passos":["Abra Fiscal e entre em \"Simulação de Impostos\".","Informe a competência (mês/ano), o regime tributário e a receita bruta do período.","Para meses a partir de 01/2027, informe os créditos de CBS das compras.","Clique em \"Simular\" e confira o resultado.","Para guardar, clique em \"Salvar simulação\"."],"dica":"A alíquota oficial da CBS de 2027 ainda será confirmada; por isso ela é um parâmetro que você pode ajustar na aba \"Parâmetros (Alíquotas)\".","palavras":["2027","reforma","pis","cofins","cbs","simulação"]},{"id":"como-simples-das","tipo":"como","titulo":"Como apurar o Simples Nacional do mês (DAS)","url":"fiscal_apuracao.html","modulo":"Fiscal","resumo":"Calcula o imposto do mês a partir das notas importadas.","passos":["Primeiro importe as notas do mês (Notas Fiscais XML).","Abra Apuração do Simples Nacional e, em \"Enquadramento da empresa\", confira o início das atividades e salve.","Em \"Apurar o mês\", escolha o mês da apuração.","Informe devoluções, cancelamentos e receita de meses anteriores não importados, se houver.","Confira o resultado e clique em \"Salvar apuração\".","Depois de transmitir no PGDAS-D, registre o número do recibo e a data da entrega."],"palavras":["simples nacional","das","pgdas","imposto do mês"]},{"id":"como-cadastrar-produto-fiscal","tipo":"como","titulo":"Como cadastrar um produto ou serviço com os dados fiscais","url":"produtos.html","modulo":"Cadastros","resumo":"Os dados fiscais deixam o item pronto para a nota fiscal e a reforma tributária.","passos":["Abra Produtos, Insumos e Serviços.","No quadro \"Cadastro / Edição de Item\", preencha a descrição, o tipo, a unidade e os preços.","No bloco \"Dados Fiscais\", informe o NCM (8 dígitos) e, se tiver, o CEST (7 dígitos).","Preencha a origem da mercadoria e marque se o item é monofásico.","Informe o CST e a classificação tributária do IBS/CBS (cClassTrib); para serviços, o NBS e o item da LC 116.","Clique em \"Salvar Item\". O sistema avisa se algum código estiver com o formato errado."],"dica":"Em dúvida sobre NCM ou cClassTrib? Peça ao contador; códigos errados geram rejeição na nota.","palavras":["ncm","cest","nbs","cclasstrib","cst","monofásico","lc 116"]},{"id":"como-distribuir-lucros","tipo":"como","titulo":"Como registrar a distribuição de lucros aos sócios","url":"distribuicao_lucros.html","modulo":"Contábil","resumo":"Registra o dinheiro que o sócio recebeu como lucro e confere o limite do mês.","passos":["Abra Distribuição de Lucros e clique em \"Nova Distribuição\".","Escolha o sócio, a data em que o dinheiro foi disponibilizado, o valor e a origem do lucro.","Informe a data da ata de aprovação, se houver.","Clique em \"Salvar\".","Use \"Imprimir Conferência\" ou \"Exportar CSV\" para o contador."],"dica":"Ajuste o limite mensal por sócio, a alíquota do IRRF e o ano nos parâmetros da própria tela.","palavras":["dividendos","lucro","sócio","ata","irrf"]},{"id":"como-cadastrar-usuario","tipo":"como","titulo":"Como criar um usuário e definir o que ele pode acessar","url":"usuarios.html","modulo":"Sistema","resumo":"Cada pessoa entra com o próprio e-mail e só vê os módulos liberados.","passos":["Abra Utilizadores & Permissões.","Informe o e-mail (será o login) e uma senha provisória com no mínimo 10 caracteres, com letras e números.","Escolha o perfil e o tipo de acesso aos módulos; se for restrito, marque os módulos permitidos.","Clique em \"Salvar utilizador\" e avise a pessoa para trocar a senha no primeiro acesso."],"palavras":["senha","login","permissão","perfil","acesso","novo usuário","utilizador"]},{"id":"como-backup","tipo":"como","titulo":"Como fazer backup dos dados","url":"backup_dados.html","modulo":"Sistema","resumo":"Gera uma cópia de segurança dos seus dados para guardar fora do sistema.","passos":["Abra Backup dos Dados.","Escolha entre \"Somente a empresa selecionada\" ou \"Todas as empresas\".","Clique em \"Gerar backup agora\" e guarde o arquivo em local seguro."],"palavras":["cópia de segurança","salvar dados","exportar tudo"]},{"id":"como-calendario-fiscal","tipo":"como","titulo":"Como registrar que uma obrigação foi transmitida","url":"calendario_fiscal.html","modulo":"Fiscal","resumo":"Guarda o protocolo da entrega para provar que a obrigação foi cumprida.","passos":["Abra o Calendário Fiscal e filtre a empresa, a competência e o tipo de documento.","Na obrigação, abra \"Registrar Transmissão\".","Informe o número do protocolo, a data da transmissão e anexe o comprovante.","Clique em \"Salvar transmissão\"."],"palavras":["protocolo","prazo","obrigação","transmissão","guia"]},{"id":"como-certificado","tipo":"como","titulo":"Como cadastrar um certificado digital","url":"certificados_digitais.html","modulo":"Fiscal","resumo":"Controle a validade dos certificados para não ser pego de surpresa.","passos":["Abra Certificados Digitais.","Escolha o tipo do certificado (A1 ou A3) e o titular; informe nome, CNPJ/CPF e a validade final (obrigatória).","Preencha emissor, número de série e onde ele está guardado.","Clique em \"Salvar certificado\". O sistema avisa no topo quando estiver vencido ou perto de vencer."],"dica":"Para certificado A1, use \"Conferir e guardar\" para guardar o arquivo no cofre.","palavras":["a1","a3","validade","vencimento","assinatura"]},{"id":"norma-reforma-2027","tipo":"norma","titulo":"Reforma tributária: o que muda em 2026 e 2027 (IBS, CBS)","url":"fiscal_contabil.html","modulo":"Fiscal","resumo":"Em 2026 a CBS (0,9%) e o IBS (0,1%) são de teste e destacados nas notas. Em 2027 a CBS passa a substituir PIS e Cofins. Simples Nacional e MEI passam a ter de informar IBS/CBS nas notas a partir de 04/01/2027.","passos":["No ERP: cadastre NCM, cClassTrib e CST nos produtos (Produtos).","Importe as notas e acompanhe a aba \"Apuração IBS/CBS\" (Notas Fiscais XML).","Use a \"Simulação de Impostos\" para estimar 2027.","Reconfira as datas com o contador antes de cada virada: a regulamentação ainda recebe atos novos."],"dica":"A alíquota oficial da CBS de 2027 ainda não foi confirmada; o sistema não a fixa.","palavras":["ibs","cbs","pis","cofins","2027","is","imposto seletivo","simples","mei"],"fonte":"Lei Complementar 214/2025; NT 2025.002 da NF-e (versão 1.53)","revisado":"24/11/2026"},{"id":"norma-licenca-paternidade","tipo":"norma","titulo":"Licença-paternidade e salário-paternidade (Lei 15.371/2026)","url":"folha_rh.html#rubricas","modulo":"Folha e RH","resumo":"A licença-paternidade passa de 5 para 10 dias em 01/01/2027, 15 dias em 2028 e 20 dias em 2029, com remuneração integral. A empresa paga e é reembolsada pelo INSS.","passos":["Na Folha, aba \"Rubricas (referência)\", use a rubrica interna 1615 (Salário-Paternidade).","Confira a natureza e as incidências na Tabela 3 oficial do eSocial antes de usar (as regras novas entram na etapa de 14/12/2026)."],"dica":"O ERP não transmite o eSocial: a transmissão é feita pelo programa de folha da empresa.","palavras":["paternidade","licença","pai","inss","reembolso","esocial"],"fonte":"Lei 15.371/2026; NT S-1.3 nº 07/2026 do eSocial","revisado":"24/11/2026"},{"id":"norma-esocial-s13","tipo":"norma","titulo":"eSocial: NT S-1.3 nº 07/2026 — datas das etapas","url":"folha_rh.html","modulo":"Folha e RH","resumo":"A norma tem etapas, cada uma com data no ambiente restrito e outra em produção: 25/09 e 29/09/2026; 13/10 e 26/10; 09/11 e 23/11; 07/12 e 14/12 (salário-paternidade). O campo de observações do S-8200 só entra em produção em 18/01/2027.","dica":"Quem transmite o eSocial é o programa de folha; o ERP organiza os dados do funcionário (nome social, cargo, CBO, local de trabalho e dependentes com CPF).","palavras":["esocial","s-1.3","nota técnica","s-2200","dependentes","cpf"],"fonte":"Nota Técnica S-1.3 nº 07/2026 (gov.br/esocial)","revisado":"24/11/2026"},{"id":"como-cadastrar-funcionario","tipo":"como","titulo":"Como cadastrar um funcionário ou sócio","url":"folha_rh.html#funcionarios","modulo":"Folha e RH","resumo":"Faça o cadastro completo, no padrão do eSocial, para depois calcular folha, férias e rescisão.","passos":["Abra Folha de Pagamento e fique na aba \"Funcionários & Sócios\".","Preencha os dados pessoais. Os campos com * são obrigatórios: nome completo, CPF, data de nascimento, sexo, raça/cor, estado civil, grau de instrução, nome da mãe e PIS/NIS/NIT.","Preencha os documentos que o funcionário tiver (RG, CTPS, CNH) e os dados do contrato, como cargo e admissão.","Se ele tiver filhos ou outros dependentes, clique em \"Adicionar dependente\" e informe nome, CPF e parentesco. Os dependentes mudam o cálculo do IRRF.","Clique em \"Gravar Colaborador\". Ele aparece no \"Quadro de Pessoal Cadastrado\".","Para corrigir depois, use a edição da linha no quadro; o botão \"Cancelar edição\" desiste da alteração."],"dica":"Tem o CPF mas não o resto? Use \"Consultar na Receita\" ao lado do CPF para conferir o nome. Muitos funcionários de uma vez: use a importação por planilha.","palavras":["admissão","colaborador","contratar","cadastro de funcionário","dependente","cpf","pis","ctps","esocial","s-2200","sócio"],"revisado":"24/11/2026"},{"id":"como-importar-funcionarios","tipo":"como","titulo":"Como importar vários funcionários por planilha","url":"importar_funcionarios.html","modulo":"Folha e RH","resumo":"Em vez de digitar um por um, preencha o modelo e traga todos de uma vez.","passos":["Abra \"Importar funcionários por planilha\" (Folha e RH).","Clique em \"Baixar modelo de planilha\" e preencha uma linha por funcionário, sem apagar nem mudar a ordem das colunas.","Volte à tela, escolha o arquivo preenchido e confira a prévia: cada linha mostra a situação (pronta ou com erro) e o motivo.","Corrija na planilha o que estiver com erro e envie de novo.","Clique em \"Importar agora\".","Use \"Imprimir conferência\" para guardar a lista do que foi importado."],"dica":"Confira CPF e data de nascimento antes de importar; são os campos que mais dão erro.","palavras":["planilha","importar colaboradores","carga de funcionários","excel","modelo","migrar"],"revisado":"24/11/2026"},{"id":"como-calcular-folha-clt","tipo":"como","titulo":"Como calcular a folha de pagamento do mês (CLT)","url":"folha_rh.html#folha_clt","modulo":"Folha e RH","resumo":"Calcule salários, INSS, IRRF e FGTS do mês de uma vez e feche a competência.","passos":["Abra Folha de Pagamento e entre na aba \"Folha CLT\".","Escolha a Competência (mês/ano).","Se a empresa tem encargos próprios (RAT, FAP, Terceiros), confira os campos e clique em \"Salvar encargos\". Se a empresa recolhe o INSS patronal separado da folha, marque essa opção.","Clique em \"Calcular e gravar folha\" e depois em \"Resumo da folha\" para conferir os totais.","Estando tudo certo, clique em \"Fechar competência\". Se precisar mexer depois, o botão \"Reabrir\" desfaz o fechamento.","Clique em \"Contabilizar folha\" para gerar os lançamentos contábeis e em \"Enviar guias ao Contas a Pagar\" para programar o pagamento das guias.","\"Imprimir quadro\" gera o relatório da folha para arquivo."],"dica":"As tabelas de INSS e IRRF usadas ficam na aba \"Tabelas (referência)\". O cálculo é de apoio: confira com a contabilidade antes de pagar.","palavras":["holerite","salário","folha mensal","inss","irrf","fgts","encargos","rat","fap","fechar competência","guias","contabilizar"],"revisado":"24/11/2026"},{"id":"como-calcular-ferias","tipo":"como","titulo":"Como calcular férias","url":"folha_rh.html#ferias13","modulo":"Folha e RH","resumo":"Informe o início, os dias e o salário para ver o valor das férias com o terço constitucional.","passos":["Abra Folha de Pagamento > aba \"Férias e 13º\", bloco de Férias.","Escolha o Funcionário (CLT).","Informe o Início das férias e os dias de férias gozadas (de 5 a 30).","Se o funcionário vender dias, preencha \"Dias vendidos - abono\" (de 0 a 10).","Confira o salário mensal, a média de variáveis (horas extras, comissões) e os dependentes.","Clique em \"Calcular férias\" e, para entregar ao funcionário, em \"Imprimir demonstrativo\"."],"dica":"As férias levam o acréscimo de 1/3 e o pagamento deve sair até 2 dias antes do início (CLT, art. 145). O fracionamento em até 3 períodos exige que um deles tenha 14 dias ou mais.","palavras":["férias","abono pecuniário","vender férias","um terço","1/3","descanso","recibo de férias"],"fonte":"CLT, arts. 129 a 145","revisado":"24/11/2026"},{"id":"como-calcular-13o","tipo":"como","titulo":"Como calcular o 13º salário","url":"folha_rh.html#ferias13","modulo":"Folha e RH","resumo":"Calcule o 13º proporcional aos meses trabalhados e imprima o demonstrativo.","passos":["Abra Folha de Pagamento > aba \"Férias e 13º\", bloco do 13º.","Escolha o Funcionário (CLT) e o Ano do 13º.","Informe o salário mensal, a média de variáveis, os dependentes e os meses trabalhados no ano (de 1 a 12).","Clique em \"Calcular 13º\" e confira o valor.","Use \"Imprimir demonstrativo\" para guardar ou entregar."],"dica":"Prazos legais: a 1ª parcela até 30/11 e a 2ª até 20/12. Mês com 15 dias ou mais de trabalho conta como mês inteiro.","palavras":["décimo terceiro","13 salário","gratificação natalina","parcela","dezembro","proporcional"],"fonte":"Lei 4.090/1962 e Lei 4.749/1965","revisado":"24/11/2026"},{"id":"como-calcular-rescisao","tipo":"como","titulo":"Como calcular uma rescisão (demissão de funcionário) na CLT","url":"folha_rh.html#rescisao","modulo":"Folha e RH","resumo":"Veja o acerto do desligamento antes de efetivar e depois registre.","passos":["Abra Folha de Pagamento > aba \"Rescisão\".","Escolha o Funcionário (CLT ativo) e informe a Data do desligamento.","Escolha o Motivo (por exemplo, sem justa causa, pedido de demissão, acordo) e o tipo de Aviso prévio.","Informe a média de variáveis, quantos períodos de férias vencidas existem (0 a 2), o saldo do FGTS conforme o extrato e outros descontos, se houver.","Clique em \"Calcular rescisão\" e confira cada verba.","\"Imprimir prévia\" gera o rascunho para conferência com o funcionário ou a contabilidade.","Estando certo, clique em \"Efetivar rescisão\". Ela passa para a lista \"Rescisões efetivadas\"."],"dica":"O pagamento das verbas rescisórias tem prazo de 10 dias corridos após o término do contrato (CLT, art. 477). Na dispensa sem justa causa a multa do FGTS é de 40%; no acordo, 20%.","palavras":["demissão","desligamento","aviso prévio","multa fgts","trct","acerto","verbas rescisórias","justa causa","pedido de demissão"],"fonte":"CLT, arts. 477 e 484-A; Lei 12.506/2011","revisado":"24/11/2026"},{"id":"como-calcular-prolabore","tipo":"como","titulo":"Como calcular o pró-labore do sócio","url":"folha_rh.html#pro_labore","modulo":"Folha e RH","resumo":"Registre a retirada mensal do sócio administrador com INSS e IRRF calculados.","passos":["Abra Folha de Pagamento > aba \"Pró-labore\".","Escolha a Competência e o Sócio (os sócios vêm do cadastro em \"Funcionários & Sócios\"; se o sócio não aparece, cadastre-o primeiro).","Confira CPF e Nº de dependentes (IRRF).","Digite o Valor Bruto (R$); o campo é editável.","Clique em \"Calcular e Registrar\". O sistema mostra INSS e IRRF e deixa o pró-labore da competência registrado."],"dica":"O pró-labore tem INSS e IRRF, mas não tem FGTS. Lucro distribuído é outra coisa: use \"Distribuição de Lucros\".","palavras":["pró labore","retirada do sócio","administrador","sócio","remuneração do sócio","inss do sócio","prolabore"],"revisado":"24/11/2026"},{"id":"como-ver-tabelas-inss-irrf","tipo":"como","titulo":"Onde ver as tabelas de INSS e IRRF usadas no cálculo","url":"folha_rh.html#tabelas","modulo":"Folha e RH","resumo":"A aba Tabelas mostra as faixas progressivas de INSS e IRRF do ano, só para consulta.","passos":["Abra Folha de Pagamento > aba \"Tabelas (referência)\".","Confira o ano de vigência no topo (ANO).","Veja a \"Tabela INSS (progressiva)\" e a \"Tabela IRRF mensal (progressiva com dedução)\"."],"dica":"São tabelas de referência: não alteram o cálculo sozinhas. Se a lei mudar, a contabilidade confirma os valores novos.","palavras":["tabela inss","tabela irrf","faixas","alíquota","dedução","dependente","imposto de renda"],"revisado":"24/11/2026"},{"id":"duvida-rescisao-calcular-efetivar","tipo":"duvida","titulo":"Qual a diferença entre \"Calcular rescisão\" e \"Efetivar rescisão\"?","url":"folha_rh.html#rescisao","modulo":"Folha e RH","resumo":"\"Calcular\" só mostra o resultado para você conferir (e imprimir a prévia). \"Efetivar\" registra o desligamento e leva a rescisão para a lista de efetivadas.","dica":"Calcule quantas vezes precisar; só efetive quando o valor estiver conferido.","palavras":["efetivar","prévia","desligar","gravar rescisão"],"revisado":"24/11/2026"},{"id":"duvida-reabrir-competencia","tipo":"duvida","titulo":"Fechei a competência por engano. Como corrijo?","url":"folha_rh.html#folha_clt","modulo":"Folha e RH","resumo":"Na aba Folha CLT, escolha a mesma competência e clique em \"Reabrir\". Depois ajuste, calcule de novo e feche outra vez.","dica":"Se a folha já foi contabilizada, avise a contabilidade para refazer os lançamentos.","palavras":["reabrir","fechamento","corrigir folha","competência fechada","desfazer"],"revisado":"24/11/2026"},{"id":"duvida-prolabore-fgts","tipo":"duvida","titulo":"Sócio tem FGTS ou 13º sobre o pró-labore?","url":"folha_rh.html#pro_labore","modulo":"Folha e RH","resumo":"Não. O pró-labore não gera FGTS, férias nem 13º. Ele tem INSS e IRRF. O sócio só tem esses direitos se também for empregado CLT da empresa.","palavras":["fgts do sócio","13 do sócio","férias do sócio","direitos do sócio"],"revisado":"24/11/2026"},{"id":"como-importar-plano-padrao","tipo":"como","titulo":"Como importar o plano de contas padrão","url":"contabilidade.html#plano","modulo":"Contábil","resumo":"Comece a escrituração com um plano de contas pronto, em vez de criar conta por conta.","passos":["Abra Escrituração Contábil, escolha a empresa no campo \"Empresa (escrituração)\" e entre na aba \"Plano de Contas\".","Clique em \"Importar plano padrão\".","Confira a lista: as contas sintéticas são os grupos (Ativo, Passivo, Receitas...) e as analíticas são as que recebem lançamento.","Para acrescentar uma conta que falta, use \"Nova conta\"; para achar uma conta, use o campo \"Buscar conta\" e o filtro \"Mostrar\"."],"dica":"Se a empresa já tem plano no Domínio, importe o dela (por planilha ou ECD) em vez do padrão.","palavras":["plano de contas","importar plano","contas padrão","estrutura contábil","começar contabilidade"],"revisado":"24/11/2026"},{"id":"como-criar-conta-contabil","tipo":"como","titulo":"Como criar uma conta contábil nova","url":"contabilidade.html#plano","modulo":"Contábil","resumo":"Cadastre uma conta que não existe no plano para poder lançar nela.","passos":["Na aba \"Plano de Contas\", clique em \"Nova conta\".","Escolha a \"Conta superior (grupo)\" em que ela vai ficar.","Informe o Código e a Descrição.","Em Tipo, escolha \"Analítica\" se ela vai receber lançamentos, ou \"Sintética\" se for só um grupo.","Na Natureza do saldo, deixe \"Automática (pelo grupo)\". Contas redutoras, como \"(-) Depreciação Acumulada\", têm natureza contrária à do grupo: escolha Devedora ou Credora.","Clique em \"Salvar\"."],"dica":"O código \"Red.\" (reduzido) é um número curto que acelera a digitação dos lançamentos.","palavras":["nova conta","código reduzido","analítica","sintética","natureza do saldo","redutora","depreciação"],"revisado":"24/11/2026"},{"id":"como-fazer-lancamento-contabil","tipo":"como","titulo":"Como fazer um lançamento contábil","url":"contabilidade.html#lanc","modulo":"Contábil","resumo":"Registre um fato contábil com débito e crédito; o sistema só grava quando os dois lados fecham.","passos":["Abra Escrituração Contábil > aba \"Lançamentos\".","Informe a Data e o Histórico (uma frase explicando o fato).","Na \"Linha de débito\", digite o código, o reduzido ou parte do nome da conta e escolha na lista; informe o valor. Faça o mesmo na \"Linha de crédito\".","Precisa de mais linhas? Os botões \"Linha de débito\" e \"Linha de crédito\" acrescentam outras.","Se faltar uma diferença, o botão \"Equilibrar\" completa a linha que falta.","Clique em \"Lançar\". O lançamento aparece no \"Diário (lançamentos do mês)\" logo abaixo."],"dica":"O lançamento só é gravado quando o total dos débitos é igual ao total dos créditos. Em mês fechado não dá para lançar nem excluir.","palavras":["débito","crédito","partida dobrada","diário","lançar","histórico","contabilizar","equilibrar"],"revisado":"24/11/2026"},{"id":"como-gerar-razao","tipo":"como","titulo":"Como ver o razão de uma conta","url":"contabilidade.html#razao","modulo":"Contábil","resumo":"O razão mostra, em ordem de data, tudo o que passou por uma conta e o saldo depois de cada movimento.","passos":["Abra Escrituração Contábil > aba \"Razão\".","Escolha a Conta e o período (De / Até).","Clique em \"Gerar razão\" e confira os movimentos.","Use \"Imprimir\" para guardar ou entregar."],"palavras":["razão analítico","extrato da conta","movimentação da conta","livro razão"],"revisado":"24/11/2026"},{"id":"como-gerar-balancete","tipo":"como","titulo":"Como gerar o balancete","url":"contabilidade.html#bal","modulo":"Contábil","resumo":"O balancete lista o saldo de cada conta no período e serve para conferir se a escrituração fecha.","passos":["Abra Escrituração Contábil > aba \"Balancete\".","Informe o período (De / Até).","Escolha até que nível detalhar: Grupos (nível 2), Subgrupos (nível 3) ou Todas as contas.","Decida se quer ocultar ou mostrar as contas sem saldo nem movimento.","Clique em \"Gerar balancete\" e, se precisar, em \"Imprimir\"."],"dica":"Se o balancete não fecha, procure o lançamento com problema no razão da conta ou no Diário.","palavras":["balancete de verificação","saldos das contas","conferir contabilidade","fechamento"],"revisado":"24/11/2026"},{"id":"como-gerar-dre-contabil","tipo":"como","titulo":"Como gerar a DRE (resultado do exercício)","url":"contabilidade.html#dre","modulo":"Contábil","resumo":"A DRE mostra receitas, custos e despesas do período e o lucro ou prejuízo.","passos":["Abra Escrituração Contábil > aba \"DRE\".","Informe De / Até, ou use os atalhos \"Mês atual\" e \"Ano atual\".","Clique em \"Gerar DRE\" e confira o resultado.","Use \"Imprimir\" para guardar."],"dica":"Existe também a tela \"DRE Gerencial\" (menu Contábil), que mostra a visão gerencial mensal, acumulada ou anual.","palavras":["dre","lucro","prejuízo","resultado","receitas e despesas","demonstração do resultado"],"revisado":"24/11/2026"},{"id":"como-gerar-balanco-patrimonial","tipo":"como","titulo":"Como gerar o Balanço Patrimonial","url":"contabilidade.html#bp","modulo":"Contábil","resumo":"O balanço mostra o que a empresa tem (ativo), o que deve (passivo) e o patrimônio líquido em uma data.","passos":["Abra Escrituração Contábil > aba \"Balanço\".","Escolha a data em \"Posição em\".","Escolha o nível de detalhe (Subgrupos ou Todas as contas).","Clique em \"Gerar balanço\" e depois em \"Imprimir\", se quiser guardar."],"dica":"Antes de gerar, confira se os saldos de abertura dos bancos foram lançados; sem eles o banco aparece negativo.","palavras":["balanço","patrimônio","ativo","passivo","posição patrimonial","bp"],"revisado":"24/11/2026"},{"id":"como-integrar-financeiro-contabilidade","tipo":"como","titulo":"Como levar o Financeiro para a contabilidade","url":"contabilidade.html#fin","modulo":"Contábil","resumo":"Transforme o que foi pago, recebido e transferido no Financeiro em lançamentos contábeis automáticos.","passos":["Abra Escrituração Contábil > aba \"Financeiro\" (só quem escritura a contabilidade da empresa usa esta aba).","Escolha o período (De / Até) e clique em \"Atualizar\".","1) Vínculos: diga a qual conta do plano corresponde cada banco/caixa e cada categoria de despesa e de receita. O botão \"Sugerir vínculos\" propõe os que ele conseguir; confira e corrija. Só contas analíticas.","2) Saldos de abertura: uma única vez, informe o saldo que cada banco tinha no dia anterior ao início da contabilidade (veja no extrato) e clique em \"Lançar saldos de abertura\".","3) Movimentos a lançar: confira a lista e clique em \"Gerar lançamentos\". Conta paga vira débito na despesa e crédito no banco; conta recebida, débito no banco e crédito na receita; transferência, débito no banco de destino e crédito no de origem.","4) Se algum título mudou depois no Financeiro, ele aparece em \"Lançamentos que mudaram\": exclua o lançamento antigo e ele volta à lista já com o valor correto."],"dica":"Cada título só é lançado uma vez. O botão \"Refazer o período\" serve para gerar de novo um período.","palavras":["integração financeiro","contabilizar pagamentos","de-para","vínculos","saldo de abertura","automatizar lançamentos","banco negativo"],"revisado":"24/11/2026"},{"id":"como-fechar-periodo","tipo":"como","titulo":"Como fechar (e reabrir) um mês na contabilidade","url":"contabilidade.html#per","modulo":"Contábil","resumo":"Mês fechado não aceita lançamento nem exclusão; é a garantia de que os números não mudam depois de entregues.","passos":["Abra Escrituração Contábil > aba \"Períodos\".","Escolha o mês e feche.","Para corrigir algo depois, a contabilidade reabre o mês; fica registrado no histórico.","Faça a correção e feche o mês de novo."],"dica":"Feche o mês só depois de conferir balancete, DRE e integração com o Financeiro.","palavras":["fechamento de período","travar mês","reabrir mês","encerrar competência","histórico de fechamento"],"revisado":"24/11/2026"},{"id":"como-importar-planilhas-contabeis","tipo":"como","titulo":"Como importar plano, saldos e lançamentos por planilha","url":"importar_planilhas.html","modulo":"Contábil","resumo":"Para quem não tem arquivo ECD (como empresas do Simples): traga os dados do Domínio exportados em planilha CSV.","passos":["Abra \"Importar planilhas contábeis\" (volta para a Contabilidade pelo link no topo).","A ordem importa: 1º Plano de contas, 2º Saldos (balancete), 3º Diário (lançamentos). Escolha a etapa em \"O que você vai importar?\".","Clique em \"Baixar modelo de planilha\" da etapa e preencha (ou salve a planilha do Domínio em CSV no mesmo formato).","Escolha o arquivo e confira o resumo: cada linha mostra a situação e o motivo. O sistema confere contas existentes, débito igual a crédito, datas e valores.","Corrija o que estiver com erro e envie de novo.","Clique em \"Importar agora\" e use \"Imprimir conferência\" para guardar o resultado."],"dica":"Importar o mesmo arquivo de novo não duplica nada.","palavras":["csv","planilha do domínio","migrar contabilidade","importar saldos","importar diário","importar balancete"],"revisado":"24/11/2026"},{"id":"como-importar-ecd-dominio","tipo":"como","titulo":"Como importar a contabilidade do Domínio pelo arquivo ECD","url":"importar_dados.html","modulo":"Contábil","resumo":"Traga plano de contas, saldo de abertura e lançamentos do ano a partir do SPED Contábil (ECD) gerado no Domínio.","passos":["No Domínio, gere o arquivo do SPED Contábil (ECD) da empresa e salve o .txt.","No Sacramento, abra \"Importar dados do Domínio (ECD)\" e escolha a empresa certa no topo.","Selecione o arquivo e confira o resumo. O sistema confere se o CNPJ do arquivo é o da empresa, se débitos e créditos fecham e se as contas existem.","Clique em \"Importar agora\" e use \"Imprimir conferência\" para guardar."],"dica":"Importar o mesmo arquivo de novo não duplica nada. Se o CNPJ não bater, você escolheu a empresa errada.","palavras":["ecd","sped contábil","domínio","migração","importar txt","escrituração contábil digital"],"revisado":"24/11/2026"},{"id":"como-importar-cadastros-planilha","tipo":"como","titulo":"Como importar clientes e fornecedores por planilha","url":"importar_cadastros.html","modulo":"Cadastros","resumo":"Cadastre vários parceiros de uma vez, usando a planilha do Domínio em CSV ou o nosso modelo.","passos":["Abra \"Importar cadastros por planilha\" (a partir de Parceiros).","Clique em \"Baixar modelo de planilha\" e preencha, ou use a planilha do Domínio salva como CSV.","Escolha o centro de custo (obrigatório no cadastro de parceiros) e o arquivo.","Confira o resumo: o sistema barra CNPJ/CPF inválido, repetido ou que já existe.","Clique em \"Importar agora\" e depois em \"Imprimir conferência\"."],"dica":"Importar o mesmo arquivo de novo não duplica nada e não altera quem já está cadastrado.","palavras":["importar clientes","importar fornecedores","parceiros","csv","cadastro em lote","planilha de cadastro"],"revisado":"24/11/2026"},{"id":"duvida-analitica-sintetica","tipo":"duvida","titulo":"Qual a diferença entre conta analítica e sintética?","url":"contabilidade.html#plano","modulo":"Contábil","resumo":"Conta sintética é um grupo: só soma as contas filhas e não recebe lançamento. Conta analítica é a que recebe os lançamentos de verdade.","dica":"Na lista do plano, use o filtro \"Só analíticas (recebem lançamento)\" para ver as contas que você pode usar.","palavras":["analítica","sintética","grupo","conta mãe","receber lançamento"],"revisado":"24/11/2026"},{"id":"duvida-lancamento-nao-grava","tipo":"duvida","titulo":"Por que o lançamento contábil não grava?","url":"contabilidade.html#lanc","modulo":"Contábil","resumo":"O sistema só grava quando a soma dos débitos é igual à soma dos créditos, e só em mês aberto. Use o botão \"Equilibrar\" para ver a diferença e confira se o mês não está fechado na aba Períodos.","palavras":["não grava","débito diferente de crédito","erro lançamento","mês fechado","não consigo lançar"],"revisado":"24/11/2026"},{"id":"duvida-importar-duas-vezes","tipo":"duvida","titulo":"Se eu importar o mesmo arquivo duas vezes, duplica?","url":"importar_dados.html","modulo":"Contábil","resumo":"Não. As importações de planilha contábil, de ECD e de cadastros reconhecem o que já entrou e não duplicam nem alteram o que já está cadastrado.","dica":"Mesmo assim, confira o resumo antes de clicar em \"Importar agora\".","palavras":["duplicar","importar de novo","reimportar","repetido","duplicidade"],"revisado":"24/11/2026"},{"id":"duvida-banco-negativo-contabilidade","tipo":"duvida","titulo":"Por que o banco aparece negativo na contabilidade?","url":"contabilidade.html#fin","modulo":"Contábil","resumo":"Falta o saldo de abertura do banco. Na aba Financeiro, em \"Saldos de abertura dos bancos\", informe o saldo do dia anterior ao início da contabilidade e clique em \"Lançar saldos de abertura\". Isso é feito uma vez só.","dica":"O saldo vem do extrato do banco, não do cadastro de Contas Bancárias.","palavras":["banco negativo","saldo inicial","saldo de abertura","caixa negativo","conta bancária negativa"],"revisado":"24/11/2026"},{"id":"como-cadastrar-conta-bancaria","tipo":"como","titulo":"Como cadastrar uma conta bancária, caixa ou cartão","url":"contas_bancarias.html","modulo":"Financeiro","resumo":"Cadastre onde o dinheiro da empresa fica, para os saldos e os pagamentos ficarem certos.","passos":["Abra Contas Bancárias, Caixa e Cartões.","Em \"Cadastrar Nova Conta ou Cartão\", escolha a Categoria: Conta Bancária / Caixa ou Cartão (crédito, débito ou pré-pago).","Informe o Nome / Identificação e a Modalidade (Conta Corrente PJ, Conta Corrente PF, Poupança, Investimento ou Caixa Físico).","Escolha a Classificação no saldo consolidado: \"Disponível da Empresa\" entra no saldo; \"Conta Particular / PF\" e \"Limite / Cheque Especial / Crédito Cartão\" não entram.","Preencha banco, agência e conta (ou os dados do cartão) e o saldo ou limite atual.","Clique em \"Salvar Cadastro\". Para editar depois, use o botão de editar da linha."],"dica":"Cartão pré-pago recarregado todo mês: informe o valor e o dia da recarga. O saldo é calculado sozinho (recarga menos os gastos pagos no cartão desde a última recarga).","palavras":["conta corrente","banco","caixa","cartão","pré-pago","poupança","cadastrar banco","saldo","agência"],"revisado":"24/11/2026"},{"id":"como-cadastrar-centro-custo","tipo":"como","titulo":"Como cadastrar um centro de custo","url":"centros_custo.html","modulo":"Cadastros","resumo":"Centro de custo é a etiqueta que separa as despesas e receitas por área ou projeto nos relatórios e na DRE.","passos":["Abra Centros de Custo (em Cadastros & Estrutura).","Clique em \"Novo Centro de Custo\".","Confira o Código / Sigla (o sistema sugere um; ele não pode repetir na mesma empresa) e escreva o Nome.","Deixe o Status como Ativo e, se quiser, descreva a finalidade.","Clique em \"Salvar Centro de Custo\"."],"dica":"Centro que já teve lançamento não deve ser apagado: marque como Inativo, e ele fica guardado no histórico sem aparecer nos novos lançamentos.","palavras":["centro de custo","projeto","setor","departamento","classificar despesas","rateio"],"revisado":"24/11/2026"},{"id":"como-aprovar-pagamentos","tipo":"como","titulo":"Como aprovar pagamentos antes de pagar","url":"aprovacao_pagamentos.html","modulo":"Financeiro","resumo":"Libere os títulos a pagar um a um, com filtros por vencimento, fornecedor e centro de custo.","passos":["Abra Aprovação & Liberação de Pagamentos.","Filtre o que precisa ver: Status de Aprovação (Aguardando Aprovação ou Aprovados para Pagamento), período de vencimento, Centro de Custo ou fornecedor. Clique em \"Aplicar Filtros\".","Confira nos totais no topo quanto está pendente de aprovação e quanto já foi aprovado.","Na linha do título, clique em \"Aprovar\". Ele passa a aparecer como \"Liberado\".","\"Imprimir\" gera o relatório da fila de aprovação."],"dica":"A aprovação só libera o título; quem registra o pagamento (baixa) continua sendo o Contas a Pagar.","palavras":["alçada","liberar pagamento","aprovar boleto","autorizar pagamento","fila de pagamentos","aguardando aprovação"],"revisado":"24/11/2026"},{"id":"como-ver-fluxo-caixa","tipo":"como","titulo":"Como ver o fluxo de caixa","url":"fluxo_de_caixa.html","modulo":"Financeiro","resumo":"Veja entradas, saídas e saldo acumulado, e confira se os lançamentos batem com o saldo informado nas contas.","passos":["Abra Fluxo de Caixa - Entradas e Saídas.","Escolha o período (Data Início e Data Fim) e, se quiser, o Tipo de Lançamento (entradas e saídas, só entradas ou só saídas) e o Centro de Custo.","Use \"Buscar Descrição\" para achar um lançamento específico.","Confira a coluna \"Saldo Acum.\" e, no rodapé, a conciliação: saldo pelos lançamentos x saldo informado nas contas (extrato) e a diferença a conciliar.","\"Imprimir Relatório\" guarda o resultado."],"dica":"Se aparecer diferença, compare com o extrato do banco: pode faltar um lançamento ou o saldo informado na conta estar desatualizado.","palavras":["fluxo","entradas e saídas","saldo acumulado","caixa","projeção","patrimônio disponível"],"revisado":"24/11/2026"},{"id":"como-ver-extrato-analitico","tipo":"como","titulo":"Como usar o extrato analítico","url":"extrato_analitico.html","modulo":"Financeiro","resumo":"Veja todos os lançamentos de contas a pagar e a receber por vencimento, com a situação de cada um.","passos":["Abra Extrato Analítico & Movimentações.","Use os filtros: Vencimento (de/até), Tipo (entradas, saídas ou ambos), Situação (pagos/recebidos ou em aberto) e Centro de custo.","Pesquise por histórico ou favorecido, se precisar.","Os totais no topo mostram entradas, saídas, resultado e o que ainda está em aberto.","\"Imprimir Extrato Analítico\" gera o relatório."],"dica":"Para ver só o que já saiu ou entrou no banco, com saldo acumulado, use o Extrato de Conta Bancária e Caixa.","palavras":["extrato","lançamentos","rastreabilidade","em aberto","pagos","vencimento","contas a pagar e receber"],"revisado":"24/11/2026"},{"id":"como-ver-extrato-bancario","tipo":"como","titulo":"Como ver o extrato de uma conta bancária ou do caixa","url":"extrato_bancario.html","modulo":"Financeiro","resumo":"Veja as movimentações realizadas (pagas e recebidas) com saldo acumulado, por conta ou consolidado.","passos":["Abra Extrato de Conta Bancária e Caixa.","Em \"Conta bancária / origem\", escolha uma conta ou deixe \"Todas as contas (consolidado)\".","Informe a Data início e a Data fim e, se quiser, filtre só entradas ou só saídas.","Confira o saldo disponível, as entradas, as saídas e o resultado do período.","\"Imprimir Extrato\" gera o relatório."],"dica":"Este extrato é calculado pelos lançamentos do sistema. Para comparar com o extrato real do banco, use a conciliação por arquivo OFX.","palavras":["extrato do banco","saldo da conta","movimentações","conta corrente","consolidado"],"revisado":"24/11/2026"},{"id":"como-fechar-caixa","tipo":"como","titulo":"Como fazer o fechamento de caixa do período","url":"fechamento_caixa.html","modulo":"Financeiro","resumo":"Veja o que realmente entrou e saiu, com saldo inicial, movimento dia a dia e saldo final.","passos":["Abra Fechamento de Caixa.","Escolha o período por um atalho (Hoje, Últimos 7 dias, Mês atual, Mês anterior, Ano atual) ou informe Data inicial e Data final.","Se quiser, filtre por tipo de movimento e centro de custo e clique em \"Buscar\".","Confira: saldo inicial (tudo o que entrou e saiu antes da data inicial) + entradas realizadas - saídas pagas = saldo final.","Veja o detalhe em \"Fechamento dia a dia\" e em \"Movimentos do período\" e use \"Imprimir Fechamento\"."],"dica":"Só entra no fechamento o que foi efetivamente recebido ou pago; o que está em aberto não conta.","palavras":["fechamento","caixa do dia","saldo final","movimento diário","fechar o dia"],"revisado":"24/11/2026"},{"id":"como-conciliar-cartoes-pix","tipo":"como","titulo":"Como conciliar cartões, PIX e gateways","url":"conciliacao_cartoes.html","modulo":"Financeiro","resumo":"Acompanhe os recebíveis digitais por canal, com a taxa (MDR) descontada e o líquido previsto.","passos":["Abra Conciliação de Cartões, PIX & Gateways.","Clique em \"Configurar Taxas (MDR)\" e informe a taxa de cada canal. Se a taxa estiver zerada, o líquido previsto fica igual ao bruto.","Filtre por período, Canal (PIX, crédito, débito, boleto, outros) e Situação (recebidos ou em aberto).","Confira o total bruto, as taxas, o líquido previsto e quanto já foi recebido.","\"Imprimir Relatório\" guarda a conferência."],"dica":"Compare o líquido previsto com o que caiu na conta: a diferença costuma ser taxa mal parametrizada.","palavras":["mdr","taxa da maquininha","recebíveis","gateway","pix","cartão de crédito","líquido previsto","antecipação"],"revisado":"24/11/2026"},{"id":"como-contratos-recorrentes","tipo":"como","titulo":"Como cadastrar um contrato de faturamento recorrente","url":"contratos_recorrentes.html","modulo":"Financeiro","resumo":"Para mensalidades e assinaturas: cadastre o contrato uma vez e acompanhe o valor mensal.","passos":["Abra Contratos & Faturamento Recorrente.","Clique em \"Novo Contrato\".","Informe o cliente / parceiro, o objeto do contrato, o dia do vencimento, o início e fim e o valor mensal.","Salve. O contrato aparece na lista com o status (ativo ou suspenso) e o total mensal dos ativos aparece no topo.","Use os filtros por status e pesquise por cliente ou objeto para achar um contrato."],"dica":"Suspenda o contrato em vez de apagar quando o cliente pausar o serviço.","palavras":["mensalidade","assinatura","contrato","faturamento recorrente","cobrança mensal","receita recorrente"],"revisado":"24/11/2026"},{"id":"duvida-saldo-conta-nao-bate","tipo":"duvida","titulo":"Por que o saldo da conta não bate com o banco?","url":"contas_bancarias.html","modulo":"Financeiro","resumo":"O sistema calcula o saldo pelos lançamentos. O valor que você digita em cada conta serve de conferência com o extrato: se houver diferença, ela aparece em vermelho. Procure o lançamento que falta ou está duplicado.","dica":"Confira também a conciliação no rodapé do Fluxo de Caixa e use a conciliação por OFX.","palavras":["saldo errado","diferença","divergência","conferência","extrato não bate","saldo divergente"],"revisado":"24/11/2026"},{"id":"duvida-conta-pf-entra-saldo","tipo":"duvida","titulo":"Conta particular (PF) entra no saldo da empresa?","url":"contas_bancarias.html","modulo":"Financeiro","resumo":"Não. Só entram no saldo consolidado as contas marcadas como \"Disponível da Empresa\". Conta Particular / PF e limites de cheque especial ou cartão ficam de fora.","dica":"A classificação é escolhida no cadastro da conta; edite a conta para mudar.","palavras":["conta pessoal","pf","pessoa física","cheque especial","limite","entra no saldo"],"revisado":"24/11/2026"},{"id":"duvida-extrato-analitico-bancario","tipo":"duvida","titulo":"Qual a diferença entre o extrato analítico e o extrato bancário?","url":"extrato_analitico.html","modulo":"Financeiro","resumo":"O Extrato Analítico lista todos os títulos a pagar e a receber por vencimento, pagos ou em aberto. O Extrato de Conta Bancária e Caixa mostra só o que já foi pago ou recebido, com saldo acumulado por conta.","palavras":["analítico","bancário","qual extrato","diferença extratos"],"revisado":"24/11/2026"},{"id":"como-ver-livros-fiscais","tipo":"como","titulo":"Como ver e imprimir os livros fiscais (entradas e saídas)","url":"fiscal_livros.html","modulo":"Fiscal","resumo":"Registro de Entradas, Registro de Saídas e resumos, montados sozinhos a partir das notas importadas.","passos":["Primeiro importe os XML das notas em Notas Fiscais (XML).","Abra Livros Fiscais e escolha a Empresa.","Defina o período em \"De (mês)\" e \"Até (mês)\".","Escolha a aba: Registro de Saídas, Registro de Entradas, Resumo por CFOP ou Resumo mensal.","Use \"Exportar para Excel\" para levar a tabela ou \"Imprimir\" para o relatório."],"dica":"Os valores vêm do que está nos XML. Se algo está errado no livro, o erro está na nota importada ou no cadastro dela.","palavras":["livro de entradas","livro de saídas","registro de entradas","registro de saídas","resumo por cfop","livro fiscal","exportar excel","imprimir livro"],"revisado":"24/11/2026"},{"id":"como-ler-resumo-notas","tipo":"como","titulo":"Como ler o resumo das notas fiscais do mês","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"Os quadros no topo somam vendas, compras e os impostos destacados nas notas do mês escolhido.","passos":["Abra Notas Fiscais (XML) e escolha a Empresa e o Mês.","Confira os quadros: Notas de saída (mercadorias e serviços, total vendido) e Notas de entrada (total comprado).","Veja o imposto destacado: ICMS, ISS, CBS e IBS (débito nas vendas, crédito nas compras).","Filtre a lista por tipo (vendas ou compras), modelo (NF-e ou NFS-e) ou busque por cliente / fornecedor.","Clique numa nota para ver os itens dela."],"dica":"Notas canceladas não entram nas somas. O total vendido é a base usada depois no cálculo do Simples Nacional.","palavras":["resumo","total vendido","total comprado","notas de saída","notas de entrada","nf-e","nfs-e","filtrar notas"],"revisado":"24/11/2026"},{"id":"como-ver-itens-nota","tipo":"como","titulo":"Como ver os itens de uma nota (NCM, CFOP, CST IBS/CBS)","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"Abra a nota para ver cada produto ou serviço com os códigos fiscais usados.","passos":["Em Notas Fiscais (XML), encontre a nota na lista.","Clique na linha da nota.","Na janela \"Itens da nota\" confira descrição, NCM, CFOP, quantidade, valor unitário e total.","Veja também o CST IBS/CBS e o cClassTrib, usados na reforma tributária.","Clique em \"Fechar\" para voltar."],"dica":"Código fiscal errado vem do cadastro do produto no sistema de quem emitiu a nota. Peça a correção na origem.","palavras":["itens da nota","ncm","cfop","cst","cclasstrib","detalhe da nota","produto da nota"],"revisado":"24/11/2026"},{"id":"como-nota-cnpj-nao-bate","tipo":"como","titulo":"O que fazer quando o CNPJ da nota não bate com a empresa","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"O sistema decide se a nota é venda ou compra pelo CNPJ. Se o CNPJ não bate, você escolhe.","passos":["Selecione os arquivos XML na importação.","No campo \"Quando o CNPJ não bater\", escolha: \"Eu escolho em cada nota\", \"Tratar todas como VENDA (saída)\" ou \"Tratar todas como COMPRA (entrada)\".","Importe e confira na lista a coluna \"É uma…\" de cada nota.","Se importou a empresa errada, confira o campo Empresa antes de repetir."],"dica":"Quando for um lote só de compras ou só de vendas, use a opção de tratar todas, é mais rápido.","palavras":["cnpj diferente","venda ou compra","entrada ou saída","xml de outra empresa","tratar como compra","tratar como venda"],"revisado":"24/11/2026"},{"id":"como-ajustar-receita-simples","tipo":"como","titulo":"Como lançar devoluções e cancelamentos no cálculo do Simples","url":"fiscal_apuracao.html","modulo":"Fiscal","resumo":"Devoluções e cancelamentos são descontados da receita do mês; receita de meses não importados entra no RBT12.","passos":["Abra Apuração do Simples Nacional e escolha a Empresa e o Mês.","Preencha \"Devoluções de mercadorias (R$)\" e \"Cancelamentos de serviços (R$)\", se houve.","Se faltam meses de notas no sistema, informe \"Receita de meses anteriores não importados (R$)\".","Confira a receita do mês, o RBT12, a faixa, a alíquota efetiva e o DAS.","Se a empresa tem menos de 12 meses, informe o \"Início das atividades\"."],"dica":"Sem a receita dos meses anteriores o RBT12 fica baixo demais e o imposto sai menor que o devido.","palavras":["devolução","cancelamento","rbt12","receita anterior","menos de 12 meses","início das atividades","desconto da receita"],"revisado":"24/11/2026"},{"id":"como-fator-r","tipo":"como","titulo":"Como informar o Fator R (Anexo III ou V)","url":"fiscal_apuracao.html","modulo":"Fiscal","resumo":"Para serviços intelectuais, o anexo depende de quanto a folha de pagamento pesa na receita.","passos":["Em Apuração do Simples Nacional, na atividade de serviços, escolha \"Fator R — Anexo III ou V conforme a folha de pagamento\".","Informe a folha de pagamento dos 12 meses (R$).","Clique em \"Salvar enquadramento\" e confira o anexo escolhido pelo sistema e o DAS calculado.","A partir de 01/2027 a folha usa os mesmos 12 meses do RBT12, sem o mês anterior."],"dica":"Em geral, folha de 28% ou mais da receita dos 12 meses enquadra no Anexo III; abaixo disso, no Anexo V. Confirme sempre na regra vigente do Simples.","palavras":["fator r","folha de pagamento","anexo iii","anexo v","28%","fs12","serviços intelectuais"],"revisado":"24/11/2026"},{"id":"como-registrar-pgdas","tipo":"como","titulo":"Como registrar o recibo da declaração (PGDAS-D)","url":"fiscal_apuracao.html","modulo":"Fiscal","resumo":"A declaração é entregue todo mês no portal; aqui você guarda o número do recibo como prova.","passos":["Entregue a PGDAS-D no portal do Simples Nacional.","No sistema, abra a Apuração do Simples Nacional e o mês.","Preencha \"Nº do recibo da declaração (PGDAS-D)\" e a \"Data da entrega da declaração\".","Use \"Observação\" se precisar anotar algo e clique em \"Salvar apuração\".","A situação do mês passa a mostrar a declaração entregue."],"dica":"O DAS e a declaração vencem no dia 20 do mês seguinte; se cair em dia sem expediente, vale o próximo dia útil.","palavras":["pgdas","recibo","declaração","das","vencimento","entrega","simples nacional"],"revisado":"24/11/2026"},{"id":"como-guardar-certificado-cofre","tipo":"como","titulo":"Como guardar um certificado A1 no cofre","url":"certificados_digitais.html","modulo":"Fiscal","resumo":"O sistema guarda o arquivo do certificado protegido pela senha dele e nunca guarda a senha.","passos":["Abra Certificados Digitais e cadastre o certificado (tipo, titular, validade).","Escolha \"Guardar certificado A1 no cofre\".","Selecione o arquivo (.pfx ou .p12) e digite a senha do certificado só para conferir que ele abre.","Salve. Para assinar depois, escolha o certificado na lista e digite a senha."],"dica":"O cadastro de validade não contém chave privada nem senha. Para A3 (token ou cartão) só se controla a validade.","palavras":["cofre","pfx","p12","a1","a3","senha do certificado","assinatura digital","e-cnpj","e-cpf"],"revisado":"24/11/2026"},{"id":"como-filtrar-certificados-vencendo","tipo":"como","titulo":"Como ver quais certificados estão vencendo","url":"certificados_digitais.html","modulo":"Fiscal","resumo":"Filtre por situação para achar vencidos e os que vencem em 30 ou 60 dias.","passos":["Abra Certificados Digitais.","No filtro Situação, escolha: Vencidos, Vencem em até 30 dias, Vencem em até 60 dias, Válidos ou Arquivados / revogados.","Use a pesquisa por titular ou CNPJ / CPF.","Na coluna \"Validade até\" confira a data e, ao renovar, cadastre o novo certificado e arquive o antigo."],"dica":"Renove com antecedência: certificado vencido bloqueia emissão de nota e entrega de declarações.","palavras":["vencimento do certificado","vencidos","renovar certificado","aviso de vencimento","validade"],"revisado":"24/11/2026"},{"id":"como-lancar-nfse-servicos","tipo":"como","titulo":"Como registrar uma NFS-e de serviço prestado","url":"nfse_servicos.html","modulo":"P&D","resumo":"Vincule a nota de serviço ao projeto e ao tomador e acompanhe se está emitida, pendente ou cancelada.","passos":["Abra Faturamento de Serviços (NFS-e).","Escolha o Projeto vinculado e o Tomador / Cliente.","Informe o número da NFS-e, o valor, a data de emissão e o status (Emitida / Autorizada, Pendente de Emissão ou Cancelada).","Descreva os serviços prestados em \"Discriminação\" e salve."],"dica":"Esta tela controla e vincula a nota ao projeto; a emissão oficial continua no portal da prefeitura.","palavras":["nfse","nota de serviço","faturamento de serviços","projeto","tomador","p&d","nota pendente"],"revisado":"24/11/2026"},{"id":"duvida-nota-cancelada-soma","tipo":"duvida","titulo":"Nota cancelada entra nos totais e impostos?","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"Não. Notas canceladas ficam na lista, mas não entram nas somas de vendas, compras, ICMS, ISS, CBS, IBS nem no cálculo do Simples.","dica":"Nos Livros Fiscais, as notas canceladas do período aparecem à parte.","palavras":["cancelada","cancelamento","soma","total","imposto","nota cancelada"],"revisado":"24/11/2026"},{"id":"duvida-credito-cbs-compra","tipo":"duvida","titulo":"Por que a compra não gerou crédito de CBS/IBS?","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"O crédito só existe quando o fornecedor destacou IBS/CBS na nota e a compra dá direito a crédito. Consumo pessoal, por exemplo, não dá. Sem destaque na nota, o crédito fica zerado.","dica":"O saldo do mês é débito menos crédito menos o crédito acumulado de meses anteriores.","palavras":["crédito","cbs","ibs","compra sem crédito","fornecedor do simples","destaque","crédito a transportar"],"revisado":"24/11/2026"},{"id":"duvida-cbs-ibs-2026-teste","tipo":"duvida","titulo":"Por que CBS 0,9% e IBS 0,1% em 2026?","url":"fiscal_notas.html","modulo":"Fiscal","resumo":"Em 2026 as alíquotas são de teste: CBS 0,9% e IBS 0,1%. A partir de 2027 a CBS substitui o PIS e a Cofins. O cálculo do sistema é uma conferência a partir dos XML; o recolhimento oficial segue as regras da Receita e do Comitê Gestor.","dica":"Reconfirme as alíquotas oficiais antes de cada virada de ano.","palavras":["alíquota de teste","2026","2027","pis cofins","reforma tributária","cbs","ibs"],"fonte":"Reforma Tributária do Consumo (LC 214/2025)","revisado":"24/11/2026"},{"id":"duvida-das-diferente-pgdas","tipo":"duvida","titulo":"O DAS do sistema ficou diferente do PGDAS-D oficial. E agora?","url":"fiscal_apuracao.html","modulo":"Fiscal","resumo":"O sistema calcula pelas notas importadas e não separa ICMS-ST, PIS/COFINS monofásico, ISS retido pelo cliente nem isenções. Se a empresa tem essas situações, confira com o PGDAS-D oficial antes de pagar.","dica":"Confira também se todas as notas e a receita de meses anteriores foram lançadas.","palavras":["das diferente","valor divergente","monofásico","icms-st","iss retido","isenção","conferir pgdas"],"revisado":"24/11/2026"},{"id":"duvida-menos-12-meses-simples","tipo":"duvida","titulo":"Empresa nova (menos de 12 meses) calcula o Simples como?","url":"fiscal_apuracao.html","modulo":"Fiscal","resumo":"Informe o início das atividades na apuração. O sistema usa os meses de atividade para formar a base do cálculo, em vez dos 12 meses completos.","dica":"Confira o resultado com o PGDAS-D oficial no primeiro mês.","palavras":["empresa nova","início das atividades","abertura","primeiro ano","rbt12 proporcional"],"revisado":"24/11/2026"},{"id":"como-cadastrar-dados-empresa","tipo":"como","titulo":"Como preencher os dados da empresa e o logotipo","url":"dados_empresa.html","modulo":"Cadastros","resumo":"Digite o CNPJ e o sistema busca na Receita Federal os dados da empresa, os CNAEs e o quadro societário.","passos":["Abra Dados da Empresa & Logotipo.","Digite o CNPJ e clique em \"Consultar CNPJ na Receita\".","Confira razão social, nome fantasia, situação cadastral, data de abertura, CNAE principal e secundários.","Complete e-mail corporativo e telefone / WhatsApp.","Envie o logotipo (PNG ou JPG, até 500 KB). Ele aparece no topo do sistema.","Clique em \"Salvar Dados da Empresa\". \"Imprimir Ficha\" gera a ficha cadastral."],"dica":"Se a consulta não trouxer algo, preencha à mão e salve: o que você digita fica gravado.","palavras":["cnpj","razão social","logotipo","logo","receita federal","cnae","ficha da empresa","dados cadastrais"],"revisado":"24/11/2026"},{"id":"como-cadastrar-cliente-fornecedor","tipo":"como","titulo":"Como cadastrar um cliente ou fornecedor","url":"parceiros.html","modulo":"Cadastros","resumo":"Um único cadastro serve para clientes, fornecedores ou os dois, e fica ligado ao centro de custo / projeto.","passos":["Abra Clientes & Fornecedores e clique para criar um novo cadastro.","Escolha o Tipo de cadastro: Cliente, Fornecedor ou Cliente & Fornecedor.","Informe CNPJ / CPF e razão social ou nome completo.","Escolha o projeto (centro de custo) ao qual ele pertence.","Preencha contato, telefone, e-mail principal e o E-mail NF-e, que recebe as notas.","Preencha o endereço (CEP, rua, número, cidade / UF) e salve."],"dica":"O código é sugerido sozinho se você deixar em branco. Para achar depois, busque por nome, documento, cidade ou centro de custo.","palavras":["cliente","fornecedor","parceiro","cadastro de cliente","cadastro de fornecedor","cnpj","cpf","tomador"],"revisado":"24/11/2026"},{"id":"como-cadastrar-socio","tipo":"como","titulo":"Como cadastrar um sócio","url":"socios.html","modulo":"Cadastros","resumo":"Registre o quadro societário com percentual de participação, situação e datas de entrada e saída.","passos":["Abra Sócios & Acionistas e clique em \"Novo Sócio\".","Informe nome completo, CPF e função.","Informe o % de participação. O botão \"Dividir Igualmente\" sugere 100% dividido entre os sócios ativos.","Marque a situação (Ativo ou Inativo) e as datas de entrada e saída.","Clique em \"Salvar Sócio\". \"Imprimir Quadro Societário\" gera o relatório."],"dica":"O CPF não pode repetir dentro da mesma empresa. Para sócio que saiu, marque Inativo: o histórico é preservado.","palavras":["sócio","quadro societário","participação","acionista","cpf do sócio","sócio saiu"],"revisado":"24/11/2026"},{"id":"como-ver-auditoria","tipo":"como","titulo":"Como consultar a trilha de auditoria (quem fez o quê)","url":"auditoria_sistema.html","modulo":"Sistema","resumo":"Veja logins, alterações e exclusões, com data, usuário, módulo e dispositivo.","passos":["Abra Trilha de Auditoria & Logs.","Escolha o Tipo de Ação: Login no Sistema, Alteração / Edição de Registro ou Exclusão de Registro.","Informe Data Inicial e Data Final e pesquise por usuário ou detalhe.","Confira data / hora, usuário, ação, módulo e endereço IP / dispositivo.","\"Imprimir Relatório\" gera o relatório da trilha."],"dica":"Use quando um valor mudou e ninguém sabe por quê: a trilha mostra quem alterou e quando.","palavras":["auditoria","logs","trilha","quem alterou","quem excluiu","rastreabilidade","histórico de alterações","login"],"revisado":"24/11/2026"},{"id":"como-assinar-documento","tipo":"como","titulo":"Como assinar um PDF com certificado digital A1","url":"assinar_documento.html","modulo":"Sistema","resumo":"Assine PDFs com certificado ICP-Brasil A1 direto no navegador, sem enviar o documento a lugar nenhum.","passos":["Abra Assinatura Digital de Documentos.","No passo 1, escolha o documento a assinar.","No passo 2, escolha o certificado A1.","No passo 3, digite a senha do certificado.","Se quiser, marque para escrever a linha \"Assinado digitalmente por...\" na última página.","Clique em \"Assinar documento\" e baixe o arquivo assinado."],"dica":"Para conferir a assinatura, abra o PDF no Adobe Reader. O sistema registra apenas quem assinou, o nome do arquivo e o hash (impressão digital) do documento.","palavras":["assinatura digital","assinar pdf","certificado a1","icp-brasil","hash","assinar contrato"],"revisado":"24/11/2026"},{"id":"como-configurar-parametros-fiscais","tipo":"como","titulo":"Como configurar os parâmetros fiscais da empresa","url":"configuracoes_fiscais.html","modulo":"Fiscal","resumo":"Dados fiscais usados na emissão e nos cálculos: regime tributário, ambiente e endereço fiscal.","passos":["Abra Parâmetros Fiscais.","Digite o CNPJ e clique na lupa azul: o sistema traz CNAEs, porte, situação cadastral e sócios da Receita.","Escolha o Regime Tributário (Simples Nacional, Lucro Presumido ou Lucro Real) e o Ambiente de Emissão (Homologação ou Produção).","Preencha inscrição municipal e estadual, endereço fiscal e e-mail fiscal.","No Simples, informe como a empresa tratará o IBS/CBS a partir de 2027.","Clique em \"Salvar Parâmetros Fiscais\"."],"dica":"O anexo do Simples (mercadorias e serviços) não é definido aqui: é em Apuração de Impostos > Enquadramento da empresa.","palavras":["regime tributário","ambiente de emissão","homologação","produção","inscrição estadual","inscrição municipal","parâmetros fiscais","emissor"],"revisado":"24/11/2026"},{"id":"como-configurar-taxas-mdr","tipo":"como","titulo":"Como cadastrar as taxas de cartão, boleto e gateway (MDR)","url":"parametros_taxas.html","modulo":"Financeiro","resumo":"Cadastre a taxa de cada canal e bandeira para o sistema calcular o líquido dos recebíveis.","passos":["Abra Parametrização de Taxas (MDR).","Escolha o Canal / Meio: Cartão de Crédito, Cartão de Débito, Boleto Bancário ou Outros / Gateway.","Descreva a identificação (ex.: Cartão Mastercard, PIX Banco Inter).","Informe o MDR (%) e a tarifa fixa (R$).","Clique em \"Salvar\". Para corrigir, edite a linha; para remover, use \"Excluir\"."],"dica":"Quanto mais detalhada a descrição, mais precisa a conciliação dos recebíveis.","palavras":["mdr","taxa da maquininha","taxa de cartão","tarifa","bandeira","gateway","boleto","parametrização de taxas"],"revisado":"24/11/2026"},{"id":"como-cadastrar-cliente-contabil","tipo":"como","titulo":"Como cadastrar um cliente na carteira do escritório contábil","url":"gestao_escritorio.html","modulo":"Escritório","resumo":"O escritório monta a carteira de clientes contábeis com consulta automática do CNPJ.","passos":["Abra Gestão do Escritório Contábil.","Em \"Novo Cliente Contábil\", digite o CNPJ e clique em \"Consultar Web\".","Confira nome, regime tributário, CNAE, inscrições e endereço.","Clique em \"Adicionar à Carteira Contábil\".","Na carteira, use os atalhos para Folha, Calendário Fiscal e Documentos, ou edite a ficha."],"dica":"Os prazos fiscais ficam no Calendário Fiscal oficial; a lista antiga desta tela foi substituída por ele.","palavras":["escritório contábil","carteira de clientes","cliente contábil","consultar cnpj","novo cliente"],"revisado":"24/11/2026"},{"id":"como-ver-quem-acessou","tipo":"como","titulo":"Como ver quem da contabilidade acessou a sua empresa","url":"acessos_contabilidade.html","modulo":"Sistema","resumo":"Transparência (LGPD): veja as permissões dadas à contabilidade e cada acesso registrado.","passos":["Abra Quem Acessou Minha Empresa.","Escolha o período: Últimos 7 dias, 30 dias, 90 dias, Todo o período ou datas específicas.","Filtre o tipo de acesso: abriu a empresa ou consultou uma tela.","Busque por empresa ou pessoa e confira a lista."],"dica":"O quadro resume as entradas pelo seletor de empresas nos últimos 30 dias.","palavras":["lgpd","quem acessou","acesso da contabilidade","transparência","permissões","privacidade"],"revisado":"24/11/2026"},{"id":"duvida-perfil-usuario-admin","tipo":"duvida","titulo":"Qual a diferença entre Utilizador e Administrador?","url":"usuarios.html","modulo":"Sistema","resumo":"O Administrador tem acesso total e gerencia os utilizadores. O Utilizador acessa apenas o que for liberado: todos os módulos ou somente os módulos marcados.","dica":"Dê o perfil Administrador a poucas pessoas e libere ao restante só os módulos de que precisam.","palavras":["administrador","utilizador","permissão","acesso aos módulos","perfil","quem pode ver","restringir acesso"],"revisado":"24/11/2026"},{"id":"duvida-senha-provisoria","tipo":"duvida","titulo":"Qual a regra da senha provisória do usuário?","url":"usuarios.html","modulo":"Sistema","resumo":"A senha provisória deve ter no mínimo 10 caracteres, com letras e números. As senhas ficam protegidas pelo sistema de autenticação e nunca aparecem na tela. Cada pessoa troca a própria senha depois.","dica":"O e-mail cadastrado é o login da pessoa.","palavras":["senha","senha provisória","trocar senha","login","esqueci a senha","10 caracteres"],"revisado":"24/11/2026"},{"id":"duvida-certificado-a3-assinatura","tipo":"duvida","titulo":"Por que meu certificado A3 não aparece na assinatura de documentos?","url":"assinar_documento.html","modulo":"Sistema","resumo":"Certificados A3 (token ou cartão) não podem ser usados por uma página web sem um programa auxiliar instalado no computador. Por isso só os certificados A1 aparecem para assinar aqui.","dica":"Para assinar com A3, use o programa do próprio token no computador.","palavras":["a3","token","cartão","certificado não aparece","assinatura","a1"],"revisado":"24/11/2026"},{"id":"duvida-simples-ibs-cbs-opcao","tipo":"duvida","titulo":"IBS/CBS no Simples: dentro do DAS ou regime regular?","url":"configuracoes_fiscais.html","modulo":"Fiscal","resumo":"O Simples Nacional pode apurar IBS/CBS dentro do DAS (padrão) ou optar pelo regime regular (híbrido), que gera crédito ao cliente. A janela de opção para 2027 foi em setembro de 2026: confirme com a contabilidade o que foi escolhido.","dica":"A escolha fica em Parâmetros Fiscais, no campo IBS/CBS a partir de 2027.","palavras":["simples nacional","ibs","cbs","regime regular","híbrido","das","2027","opção"],"revisado":"24/11/2026"}]);
